import unittest

from app.client import build_client
from app.config import load_config


class HoldoutTests(unittest.TestCase):
    def test_retries_accepts_a_numeric_string(self):
        config = load_config({"retries": "5"})
        self.assertEqual(config["retries"], 5)
        self.assertIsInstance(config["retries"], int)
        self.assertNotIsInstance(config["retries"], bool)

    def test_retries_rejects_invalid_values(self):
        for value in ("many", -1, 0, True, 2.5):
            with self.assertRaises(ValueError):
                load_config({"retries": value})

    def test_base_url_requires_https(self):
        with self.assertRaises(ValueError):
            load_config({"base_url": "http://reports.internal"})

    def test_base_url_rejects_a_missing_host(self):
        with self.assertRaises(ValueError):
            load_config({"base_url": "https:///"})

    def test_timeout_accepts_padded_strings_and_keeps_the_default(self):
        self.assertEqual(load_config({"timeout": " 12 "})["timeout_s"], 12)
        self.assertEqual(load_config({})["timeout_s"], 30)

    def test_client_exposes_normalized_values(self):
        client = build_client({"timeout": "9", "retries": "7", "base_url": "https://reports.internal/"})
        self.assertIsInstance(client.timeout_s, int)
        self.assertIsInstance(client.retries, int)
        self.assertEqual(client.base_url, "https://reports.internal")


if __name__ == "__main__":
    unittest.main()
